    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-01T00:00:00Z",
      "updated_at": "2026-06-01T00:00:00Z",
      "created_by": "personal_trainer",
      "difficulty": "intermediate",
      "language": "en",
      "estimated_duration_days": 84
    },
    "goals": [
      {
        "id": "strength_gain_primary",
        "type": "primary",
        "category": "strength",
        "name": "Increase overall strength",
        "description": "Progressive overload across compound movements with cycle-aware intensity modulation"
      },
      {
        "id": "consistency_secondary",
        "type": "secondary",
        "category": "consistency",
        "name": "Maintain training consistency throughout cycle",
        "description": "Ensure training is feasible during flow days via lower-intensity sessions"
      }
    ],
